//! Staged container file transfers: export to a host/remote staging path,
//! import back into a container, and the audit row for a successful import.
//!
//! Staging paths are always generated by this feature (see the `staging`
//! submodule): remote paths live under
//! `/tmp/dbx-sshx.<token>`, local paths under the system temp dir in a
//! `dbx-sshx-<uuid>` directory. `validate_staging_path` is the only gate
//! cleanup, import and saveLocal ever consult, so an arbitrary path can
//! never be deleted, copied out of, or imported from.

use super::*;

use std::path::Path;

/// Wait cap for one `docker cp` leg (a large file can take a while).
pub const TRANSFER_TIMEOUT: Duration = Duration::from_secs(300);

/// `docker cp <id>:<container path> <staging path>` for the SSH plane.
pub fn export_command(
    engine: &EngineConfig,
    container_id: &str,
    container_path: &str,
    staging_path: &str,
) -> Result<String, String> {
    validate_container_id(container_id)?;
    let container_path = normalize_container_path(container_path)?;
    validate_staging_path(staging_path, StagingLocation::Remote)?;
    Ok(format!(
        "{}{} cp {} {}",
        engine.env_prefix(),
        engine.cli,
        exec::shell_quote(&format!("{container_id}:{container_path}")),
        exec::shell_quote(staging_path)
    ))
}

/// `docker cp <staging path> <id>:<dest>` for the SSH plane.
pub fn import_command(
    engine: &EngineConfig,
    container_id: &str,
    staging_path: &str,
    dest_path: &str,
) -> Result<String, String> {
    validate_container_id(container_id)?;
    validate_staging_path(staging_path, StagingLocation::Remote)?;
    let dest_path = normalize_container_path(dest_path)?;
    Ok(format!(
        "{}{} cp {} {}",
        engine.env_prefix(),
        engine.cli,
        exec::shell_quote(staging_path),
        exec::shell_quote(&format!("{container_id}:{dest_path}"))
    ))
}

/// `docker cp` on the local plane (argv only), returning the staged size.
/// The staged entry is `lstat`ed afterwards so a container symlink is never
/// handed back as a save source.
pub async fn export_local(
    engine: &EngineConfig,
    container_id: &str,
    container_path: &str,
    staging_path: &str,
) -> Result<u64, String> {
    validate_container_id(container_id)?;
    let container_path = normalize_container_path(container_path)?;
    validate_staging_path(staging_path, StagingLocation::Local)?;
    let source = format!("{container_id}:{container_path}");
    local_cp(engine, &source, staging_path).await?;
    local_staging_regular_file_size(staging_path)
}

/// `docker cp` staging → container on the local plane (argv only).
pub async fn import_local(
    engine: &EngineConfig,
    staging_path: &str,
    container_id: &str,
    dest_path: &str,
) -> Result<(), String> {
    validate_container_id(container_id)?;
    validate_staging_path(staging_path, StagingLocation::Local)?;
    let dest_path = normalize_container_path(dest_path)?;
    let dest = format!("{container_id}:{dest_path}");
    local_cp(engine, staging_path, &dest).await
}

async fn local_cp(engine: &EngineConfig, source: &str, dest: &str) -> Result<(), String> {
    let cli = find_local_cli(&engine.cli)
        .ok_or_else(|| format!("{} CLI not found on this machine", engine.cli))?;
    let (exit_code, output) = run_local(
        &cli,
        &["cp", source, dest],
        TRANSFER_TIMEOUT,
        engine.endpoint.as_deref(),
    )
    .await?;
    if exit_code != 0 {
        return Err(format!(
            "{} cp failed (exit {exit_code}): {output}",
            engine.cli
        ));
    }
    Ok(())
}

/// Structured audit row for a successful import: tool, container,
/// destination and size only — never file contents. Written *after* the
/// copy succeeded, so the ledger never claims an import that failed.
pub fn audit_import(data_dir: &Path, container_id: &str, dest_path: &str, size: u64) {
    let ts_ms = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|duration| duration.as_millis() as u64)
        .unwrap_or_default();
    let entry = audit_log::AuditEntry {
        ts_ms,
        tool: "docker/files/import".to_string(),
        connection_id: String::new(),
        gate: audit_log::GateOutcome::Pass,
        approval: audit_log::ApprovalTrail::None,
        outcome: audit_log::EntryOutcome::Ok,
        exit_code: None,
        duration_ms: 0,
        mode: audit_log::ExecMode::Stdio,
        command: Some(format!(
            "docker/files/import containerId={container_id} destPath={dest_path} size={size}"
        )),
        output: None,
        error: None,
    };
    if let Err(error) = audit_log::append(data_dir, &entry) {
        eprintln!("[docker] import audit append failed: {error}");
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn remote_commands_quote_staged_paths() {
        let engine = test_engine("docker", None);
        let export = export_command(
            &engine,
            "d4a7c9f1e2b3",
            "/tmp/a b",
            "/tmp/dbx-sshx.Ab12Cd/f",
        )
        .unwrap();
        assert_eq!(
            export,
            "docker cp 'd4a7c9f1e2b3:/tmp/a b' '/tmp/dbx-sshx.Ab12Cd/f'"
        );
        let import = import_command(
            &engine,
            "d4a7c9f1e2b3",
            "/tmp/dbx-sshx.Ab12Cd/f",
            "/srv/it's",
        )
        .unwrap();
        assert_eq!(
            import,
            "docker cp '/tmp/dbx-sshx.Ab12Cd/f' 'd4a7c9f1e2b3:/srv/it'\\''s'"
        );
        assert!(import_command(&engine, "d4a7c9f1e2b3", "/etc/passwd", "/srv/x").is_err());
    }
}
